edits.before:
  EventHandler.on(document, EVENT_FOCUSIN, this._onOutside)
  EventHandler.on(document, EVENT_POINTERDOWN, this._onOutside)
}

edits.after:
  EventHandler.on(document, EVENT_FOCUSIN, this._onOutside)
  EventHandler.on(document, EVENT_POINTERDOWN, this._onOutside)

  // Handle Tab key to hide the calendar and allow focus to move
  this._onTabKey = (event: KeyboardEvent) => {
    if (event.key === 'Tab' && this._isShown) {
      this.hide();
    }
  };

  document.addEventListener('keydown', this._onTabKey, true);
}

edits.before:
if (this._onTriggerClick) {
  EventHandler.off(this._positionElement, EVENT_CLICK, this._onTriggerClick)
}

if (this._calendar) {
  this._calendar.destroy()
}

edits.after:
if (this._onTriggerClick) {
  EventHandler.off(this._positionElement, EVENT_CLICK, this._onTriggerClick)
}

if (this._onTabKey) {
  document.removeEventListener('keydown', this._onTabKey, true);
  this._onTabKey = null;
}

if (this._calendar) {
  this._calendar.destroy()
}
